operation.before:
if let Some(tls) = &mut page.tls {
    if let Some(hop) = tls
        .hsts_upgrades
        .last_mut()
        .filter(|h| h.target_url == current.as_str())
    {
        hop.https_request_started = true;
    }
}

operation.after:
if let Some(tls) = &mut page.tls
    && let Some(hop) = tls
        .hsts_upgrades
        .last_mut()
        .filter(|h| h.target_url == current.as_str())
{
    hop.https_request_started = true;
}
